<?php
if (isset($_SERVER["SCRIPT_FILENAME"]) && realpath($_SERVER["SCRIPT_FILENAME"]) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
// Phase 8D Finance screens (owner only). Pure rendering over an AdmFinanceStore. Shares form helpers and base styles with the tool-management screens.
require_once __DIR__ . '/adm_tools_views.php';
require_once __DIR__ . '/adm_finance_store.php';
require_once __DIR__ . '/adm_finance_charts.php';

function admf_state(string $k): string { return '<span class="fState fs-' . admf_h($k) . '">' . admf_h(ADMF_STATES[$k] ?? $k) . '</span>'; }
function admf_url(array $p = []): string { return '/admin-center.php?' . http_build_query(['m' => 'finance'] + array_filter($p, fn($v) => $v !== '' && $v !== null && $v !== false)); }
function admf_css(): string {
  return ':root{--fc1:#2a78d6;--fc2:#eb6834;--fct:#52514e;--fok:#0a7a3d}@media (prefers-color-scheme:dark){:root{--fc1:#3987e5;--fc2:#d95926;--fct:#c3c2b7;--fok:#5fd493}}'
    . '.fNote{border:1px solid var(--line);border-left:6px solid var(--brand);border-radius:10px;background:var(--surface);padding:10px 14px;margin:10px 0;font-size:.9rem;color:var(--muted)}.fNote strong{color:var(--ink)}'
    . '.fState{display:inline-block;font-size:.72rem;font-weight:700;padding:.05rem .5rem;border-radius:999px;border:1px solid currentColor;white-space:nowrap;vertical-align:middle}.fs-recorded,.fs-terms{color:var(--ok)}.fs-estimate,.fs-hypothetical,.fs-reconstructed{color:var(--na)}.fs-target{color:var(--brand)}.fs-unavailable,.fs-synthetic{color:var(--muted)}'
    . '.fChart{margin:0 0 18px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:14px;box-shadow:0 12px 26px -22px rgba(16,32,63,.6)}.fChart figcaption{margin-bottom:6px}.fChart svg{width:100%;height:auto;display:block;max-height:340px}.fNo{margin:.4rem 0;color:var(--muted)}'
    . '.fGrid{stroke:var(--line);stroke-width:1}.fBase{stroke:var(--muted);stroke-width:1.5}.fAx{fill:var(--muted);font-size:11px}.fRowLab{font-size:12px}.fDirect{fill:var(--ink);font-size:11px;font-weight:600}.fVal{font-size:12px}.fTrack{fill:var(--line)}'
    . '.fc1{fill:var(--fc1);stroke:var(--fc1)}.fc2{fill:var(--fc2);stroke:var(--fc2)}.fBar{stroke:none}.fBar:hover{opacity:.8}.fLine{stroke-width:2.5;stroke-linejoin:round}.fLine.fc1,.fLine.fc2{fill:none}.fDash{stroke-dasharray:6 4}.fLine.fDash{stroke:var(--fct)}.fDot{stroke:var(--surface);stroke-width:2}.fDot:hover{r:6}'
    . '.fLegend{list-style:none;display:flex;flex-wrap:wrap;gap:6px 18px;margin:6px 0;padding:0;font-size:.85rem}.fKey{display:inline-block;width:14px;height:14px;border-radius:3px;margin-right:6px;vertical-align:-2px}.fKey.fc1{background:var(--fc1)}.fKey.fc2{background:var(--fc2)}.fKeyLine,.fKey.fKeyLine{height:0;border-top:3px solid var(--fc1);border-radius:0;background:none}.fKeyLine.fc2{border-top-color:var(--fc2)}.fKeyLine.fDash{border-top:3px dashed var(--fct)}'
    . '.fDet summary{cursor:pointer;min-height:44px;display:flex;align-items:center;font-weight:600;color:var(--brand)}.fDet table{font-size:.88rem}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}'
    . '.fGrid2{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,620px),1fr));gap:14px}.fTbl td,.fTbl th{white-space:nowrap}.fTbl .num{text-align:right;font-variant-numeric:tabular-nums}.fScen input{max-width:100%}';
}
function admf_nav(AdmFinanceStore $s, string $view): string {
  $tabs = ['overview' => 'Overview', 'revenue' => 'Revenue', 'advertising' => 'Advertising and sponsorship', 'projects' => 'Projects and retainers', 'expenses' => 'Expenses and profit', 'refunds' => 'Refunds and credits', 'targets' => 'Targets', 'exports' => 'Exports']; $o = '<nav aria-label="Finance sections"><ul class="tTabs tSub">';
  foreach ($tabs as $k => $l) $o .= '<li><a href="' . admt_h(admf_url($k === 'overview' ? [] : ['view' => $k])) . '"' . ($view === $k ? ' aria-current="page"' : '') . '>' . admt_h($l) . '</a></li>';
  return $o . '</ul></nav>';
}
function admf_note(AdmFinanceStore $s, array $rep): string {
  $other = array_diff(array_keys($rep['currencies']), [ADMF_PRIMARY]);
  return '<div class="fNote" role="note"><strong>How to read these figures.</strong> Amounts are <strong>recorded manually</strong> (CRM bookkeeping and finance entries) and are <strong>not bank-verified</strong>. ' . admt_h(ADMF_VAT) . ' Currencies are never combined or converted: ' . ADMF_PRIMARY . ' is shown first' . ($other ? '; also recorded in ' . admt_h(implode(', ', $other)) . ' (shown separately)' : '') . '. Missing data is shown as unavailable, not as zero.' . (!$s->finReady() ? ' <strong>Finance storage is not installed on this server</strong>: expenses, refunds and targets cannot be recorded yet; revenue pages still read the CRM.' : '') . '</div>';
}
function admf_tile(string $label, ?string $value, string $note, string $state = 'recorded'): array { return adm_tile($label, $value, $note . ' ' . ADMF_STATES[$state] . '.', 'ok'); }

/** Expense totals per category per currency up to now (cash basis). */
function admf_by_category(array $expenses, string $nowYm): array { $o = []; foreach (admf_real($expenses) as $e) { if (!empty($e['voided_at'])) continue; $t = array_sum(admf_expense_months($e, $nowYm)); if ($t > 0) $o[$e['currency']][ADMF_CATEGORIES[$e['category']] ?? $e['category']] = ($o[$e['currency']][ADMF_CATEGORIES[$e['category']] ?? $e['category']] ?? 0) + $t; } ksort($o); return $o; }
/** Monthly equivalent of the active recurring expenses (annual / 12), per currency. */
function admf_recurring_monthly(array $expenses, string $asOf): array { $o = []; foreach (admf_real($expenses) as $e) { if (!empty($e['voided_at']) || ($e['recurrence'] ?? 'none') === 'none') continue; if (!empty($e['recurrence_end']) && $e['recurrence_end'] < $asOf) continue; if ($e['entry_date'] > $asOf) continue; $o[$e['currency']] = ($o[$e['currency']] ?? 0) + ($e['recurrence'] === 'monthly' ? (int)$e['amount_minor'] : crm_div_round((int)$e['amount_minor'], 12)); } ksort($o); return $o; }

function admf_overview(AdmFinanceStore $s, array $rep, array $d, ?string $flash): string {
  $e = $rep['currencies'][ADMF_PRIMARY] ?? null; $ym = admf_ym($rep['as_of']); $lad = admf_ladder($rep, $s->targets());
  $o = '<h1>Finance</h1><p class="lead">Owner-only view of recorded revenue, expenses and progress toward the monthly targets. ' . admt_h(ADMF_PRIMARY) . ' first; nothing is invented.</p>' . admt_flash($flash) . admf_note($s, $rep);
  $has = $e && $e['has_revenue']; $mo = $e['series'][$ym] ?? null;
  $tiles = [
    admf_tile('Net income this month (' . ADMF_PRIMARY . ')', $has ? admf_money($mo['income'], ADMF_PRIMARY) : null, $has ? 'Received minus refunds, by recorded date.' : 'No revenue is recorded in ' . ADMF_PRIMARY . ' yet.'),
    admf_tile('Net income this year (' . ADMF_PRIMARY . ')', $has ? admf_money($e['ytd_income'], ADMF_PRIMARY) : null, $has ? 'January to now.' : 'No revenue is recorded in ' . ADMF_PRIMARY . ' yet.'),
    admf_tile('Monthly recurring revenue (' . ADMF_PRIMARY . ')', $e && $e['has_contracts'] ? admf_money($e['mrr'], ADMF_PRIMARY) : null, $e && $e['has_contracts'] ? 'Active recurring CRM contracts, not payments.' : 'No contracts are recorded in ' . ADMF_PRIMARY . ' yet.', 'terms'),
    admf_tile('Annual run rate (' . ADMF_PRIMARY . ')', $e && $e['has_contracts'] ? admf_money($e['arr'], ADMF_PRIMARY) : null, $e && $e['has_contracts'] ? 'MRR x 12; not a forecast.' : 'No contracts are recorded in ' . ADMF_PRIMARY . ' yet.', 'terms'),
    admf_tile('Expenses this month (' . ADMF_PRIMARY . ')', $e && $e['has_expenses'] ? admf_money($mo['expenses'], ADMF_PRIMARY) : null, $e && $e['has_expenses'] ? 'Cash basis, including recurring items.' : 'No expenses are recorded in ' . ADMF_PRIMARY . ' yet.'),
    admf_tile('Profit this month, cash basis (' . ADMF_PRIMARY . ')', $e && ($e['has_revenue'] || $e['has_expenses']) ? admf_money($mo['profit'], ADMF_PRIMARY) : null, $e && ($e['has_revenue'] || $e['has_expenses']) ? 'Net income minus expenses.' : 'Nothing is recorded to compute a profit.'),
    admf_tile('Invoiced, not yet received (' . ADMF_PRIMARY . ')', $has ? admf_money($e['outstanding'], ADMF_PRIMARY) : null, $has ? 'Invoiced minus credit notes minus received.' : 'No invoices are recorded in ' . ADMF_PRIMARY . '.'),
    adm_tile('Next target (monthly)', $lad['next_eur'] !== null ? admf_money($lad['next_eur'] * 100, ADMF_PRIMARY) : 'All steps reached', ($lad['active'] ? ($lad['income_minor'] === null ? 'No recorded income to compare yet.' : 'Recorded this month: ' . admf_money((int)$lad['income_minor'], ADMF_PRIMARY) . '.') : 'Monitoring starts December 2026.') . ' ' . ADMF_STATES['target'] . ': an aspiration, not a forecast.', 'ok'),
  ];
  $o .= adm_tiles_html($tiles);
  if ($e) {
    $labels = $rep['months']; $inc = array_map(fn($m) => $e['series'][$m]['income'], $labels); $exp = array_map(fn($m) => $e['series'][$m]['expenses'], $labels); $recd = array_map(fn($m) => $e['series'][$m]['received'], $labels);
    $tgt = null; if ($lad['next_eur'] !== null) $tgt = array_map(fn($m) => $m >= ADMF_TARGET_START ? $lad['next_eur'] * 100 : null, $labels);
    $o .= '<div class="fGrid2">' . admf_chart(['id' => 'ch-ie', 'title' => 'Net income and expenses by month (' . ADMF_PRIMARY . ')', 'desc' => 'Recorded net income and recorded expenses for the last 12 months, cash basis.', 'currency' => ADMF_PRIMARY, 'labels' => $labels, 'state' => 'recorded', 'series' => [['name' => 'Net income', 'values' => $inc, 'cls' => 1], ['name' => 'Expenses', 'values' => $exp, 'cls' => 2]]]);
    $o .= admf_chart(['id' => 'ch-tg', 'title' => 'Received versus the next target (' . ADMF_PRIMARY . ')', 'desc' => 'Recorded payments per month and the next monthly target step; targets are aspirations from December 2026, not forecasts.', 'currency' => ADMF_PRIMARY, 'labels' => $labels, 'state' => 'target', 'series' => array_values(array_filter([['name' => 'Received', 'values' => $recd, 'cls' => 1], $tgt ? ['name' => 'Next target', 'values' => $tgt, 'cls' => 1, 'kind' => 'line', 'dash' => true, 'optional' => true] : null]))]) . '</div>';
    $o .= admf_chart(['id' => 'ch-mrr', 'title' => 'Monthly recurring revenue trend (' . ADMF_PRIMARY . ')', 'desc' => 'Reconstructed from the current contract records at each month end. This is approximate, not an exact historical record.', 'currency' => ADMF_PRIMARY, 'labels' => $labels, 'state' => 'reconstructed', 'empty' => 'No recurring contracts are recorded, so there is no trend to show.', 'series' => [['name' => 'MRR (reconstructed)', 'values' => array_map(fn($m) => $e['series'][$m]['mrr'], $labels), 'cls' => 1, 'kind' => 'line']]]);
  } else $o .= admf_chart_empty('Charts', 'No finance records exist in ' . ADMF_PRIMARY . ' yet. Charts appear once contracts, payments or expenses are recorded.');
  $syn = array_sum($rep['synthetic_excluded']); $unc = 0; foreach ($rep['currencies'] as $x) $unc += $x['streams']['unclassified']['contracts'] ?? 0;
  $o .= '<section class="panel" aria-labelledby="dq-h"><h2 id="dq-h">Data quality</h2><ul><li>' . admf_state('synthetic') . ' ' . (int)$syn . ' demo record' . ($syn === 1 ? '' : 's') . ' excluded from every total.</li><li>' . (int)$rep['counts']['contracts'] . ' CRM contract' . ($rep['counts']['contracts'] === 1 ? '' : 's') . ', ' . (int)$rep['counts']['revenue'] . ' payment record' . ($rep['counts']['revenue'] === 1 ? '' : 's') . ', ' . (int)$rep['counts']['expenses'] . ' expense' . ($rep['counts']['expenses'] === 1 ? '' : 's') . ' read.</li>' . ($unc ? '<li>' . $unc . ' contract' . ($unc === 1 ? ' has' : 's have') . ' no stream in the CRM and appear as Unclassified.</li>' : '') . '<li>Legacy listing payments are kept apart from CRM revenue (see Revenue).</li></ul></section>';
  return $o;
}

function admf_money_table(array $x, string $c): string {
  $r = [['Invoiced', $x['invoiced'], 'recorded'], ['Credit notes', $x['credits'], 'recorded'], ['Net invoiced', $x['net_invoiced'], 'recorded'], ['Received', $x['received'], 'recorded'], ['Refunds', $x['refunds'], 'recorded'], ['Net income (received minus refunds)', $x['net_income'], 'recorded'], ['Invoiced, not yet received', $x['outstanding'], 'recorded'],
    ['Contracted value (confirmed contracts)', $x['contracted'], 'terms'], ['Recognized to date (contract terms)', $x['recognized'], 'terms'], ['Pipeline, stage-weighted', $x['forecast'], 'estimate']];
  $o = '<div class="scroll" role="region" aria-label="Revenue totals ' . admt_h($c) . '" tabindex="0"><table class="fTbl"><caption class="sr">Revenue totals in ' . admt_h($c) . '</caption><thead><tr><th scope="col">Measure</th><th scope="col" class="num">Amount (' . admt_h($c) . ')</th><th scope="col">Data state</th></tr></thead><tbody>';
  foreach ($r as [$l, $v, $st]) $o .= '<tr><th scope="row">' . admt_h($l) . '</th><td class="num">' . admt_h(admf_money($v, $c)) . '</td><td>' . admf_state($st) . '</td></tr>'; return $o . '</tbody></table></div>';
}
function admf_revenue(AdmFinanceStore $s, array $rep, ?string $flash): string {
  $o = '<h1>Revenue</h1><p class="lead">Recorded revenue by month, stream and currency. Each currency is its own report.</p>' . admt_flash($flash) . admf_note($s, $rep);
  if (!$rep['currencies']) $o .= '<div class="panel"><h2>No revenue records</h2><p>No contracts, payments or pipeline are recorded in the CRM yet, so there is nothing to report. Figures appear here once they are recorded in the CRM.</p></div>';
  foreach ($rep['currencies'] as $c => $x) {
    $o .= '<section class="panel" aria-labelledby="rv-' . admt_h($c) . '"><h2 id="rv-' . admt_h($c) . '">' . admt_h($c) . ($c === ADMF_PRIMARY ? ' (primary)' : ' (separate, not converted)') . '</h2>' . admf_money_table($x, $c);
    $o .= admf_chart(['id' => 'rv-m-' . $c, 'title' => 'Received per month (' . $c . ')', 'desc' => 'Recorded payments minus refunds for the last 12 months.', 'currency' => $c, 'labels' => $rep['months'], 'state' => 'recorded', 'series' => [['name' => 'Net income', 'values' => array_map(fn($m) => $x['series'][$m]['income'], $rep['months']), 'cls' => 1]]]);
    $items = []; foreach ($x['streams'] as $k => $st) $items[ADMF_STREAMS[$k] ?? $k] = $st['received'];
    $o .= admf_chart_hbars('rv-s-' . $c, 'Received by revenue stream (' . $c . ')', 'Streams are derived from CRM fields (opportunity kind, campaign package, billing period).', $c, $items, 'recorded', 'No payments are recorded against contracts yet.') . '</section>';
  }
  $o .= '<section class="panel" aria-labelledby="st-h"><h2 id="st-h">Revenue streams</h2><p class="small">Streams come from existing CRM fields only. These streams have no CRM field to separate them and show <strong>No record yet</strong>: ' . admt_h(implode('; ', ADMF_STREAMS_NO_FIELD)) . '.</p></section>';
  $o .= '<section class="panel" aria-labelledby="lg-h"><h2 id="lg-h">Legacy listing payments (kept separate)</h2><p class="small">Public featured-listing submissions marked <em>paid</em> by an administrator. ' . admf_state('recorded') . ' These are <strong>not included</strong> in any CRM total above, because the same payment may also be recorded in the CRM. Never add the two together.</p>';
  if (!$rep['legacy']) $o .= '<p>No legacy listing payments are recorded.</p>'; else { $o .= '<div class="scroll" role="region" aria-label="Legacy listing payments" tabindex="0"><table class="fTbl"><thead><tr><th scope="col">Currency</th><th scope="col" class="num">Marked paid</th><th scope="col" class="num">Count</th><th scope="col" class="num">Unpaid submissions</th></tr></thead><tbody>'; foreach ($rep['legacy'] as $c => $l) $o .= '<tr><th scope="row">' . admt_h($c) . '</th><td class="num">' . admt_h(admf_money($l['paid_minor'], $c)) . '</td><td class="num">' . (int)$l['paid_count'] . '</td><td class="num">' . (int)$l['unpaid_count'] . '</td></tr>'; $o .= '</tbody></table></div>'; }
  return $o . '</section><p><a class="tBtn" href="' . admt_h(admf_url(['view' => 'exports'])) . '">Export CSV</a></p>';
}

function admf_advertising(AdmFinanceStore $s, array $rep, ?string $flash): string {
  $ad = ['featured', 'newsletter', 'category', 'advertising', 'partnership']; $o = '<h1>Advertising and sponsorship</h1><p class="lead">Sponsorship and partnership revenue from CRM contracts, and the campaign pipeline. Quotes are estimates until a contract is confirmed.</p>' . admt_flash($flash) . admf_note($s, $rep);
  $any = false; foreach ($rep['currencies'] as $c => $x) { $rows = array_intersect_key($x['streams'], array_flip($ad)); if (!$rows) continue; $any = true;
    $o .= '<section class="panel" aria-labelledby="ad-' . admt_h($c) . '"><h2 id="ad-' . admt_h($c) . '">' . admt_h($c) . '</h2><div class="scroll" role="region" aria-label="Advertising streams ' . admt_h($c) . '" tabindex="0"><table class="fTbl"><thead><tr><th scope="col">Stream</th><th scope="col" class="num">Contracts</th><th scope="col" class="num">Received</th><th scope="col" class="num">MRR now</th></tr></thead><tbody>';
    foreach ($ad as $k) if (isset($rows[$k])) $o .= '<tr><th scope="row">' . admt_h(ADMF_STREAMS[$k]) . '</th><td class="num">' . (int)$rows[$k]['contracts'] . '</td><td class="num">' . admt_h(admf_money($rows[$k]['received'], $c)) . '</td><td class="num">' . admt_h(admf_money($rows[$k]['mrr'], $c)) . '</td></tr>';
    $o .= '</tbody></table></div><p class="small">' . admf_state('recorded') . ' ' . admf_state('terms') . '</p>' . admf_chart_hbars('ad-c-' . $c, 'Received by advertising and partnership stream (' . $c . ')', 'Recorded payments against confirmed contracts.', $c, array_map(fn($k) => $rows[$k]['received'], array_combine(array_map(fn($k) => ADMF_STREAMS[$k], array_keys($rows)), array_keys($rows))), 'recorded', 'No payments are recorded for these streams yet.') . '</section>'; }
  if (!$any) $o .= '<div class="panel"><h2>No advertising or sponsorship contracts</h2><p>No confirmed advertising or partnership contracts are recorded in the CRM yet. Nothing is estimated here.</p></div>';
  $camp = $rep['campaigns']; $o .= '<section class="panel" aria-labelledby="cp-h"><h2 id="cp-h">Campaign pipeline</h2>';
  if (!$camp['by_status']) $o .= '<p>No campaigns are recorded in the CRM.</p>'; else { $o .= '<ul class="tChips">'; foreach ($camp['by_status'] as $st => $n) $o .= '<li><span class="chip">' . admt_h(function_exists('crm_campaign_statuses') ? (crm_campaign_statuses()[$st] ?? $st) : $st) . ' · ' . (int)$n . '</span></li>'; $o .= '</ul>'; }
  if ($camp['quotes']) { $o .= '<p>Open quotes (not revenue) ' . admf_state('estimate') . ': '; $q = []; foreach ($camp['quotes'] as $c => $v) $q[] = admt_h(admf_money($v, $c)); $o .= implode(' · ', $q) . '</p>'; }
  $o .= '<p class="small">Sponsored tool placements are managed in <a class="admLink" href="/admin-center.php?m=tools&amp;view=featured">Tool management, Featured</a>. They carry no price here; revenue appears only through CRM contracts and recorded payments.</p></section>';
  $o .= '<section class="panel" aria-labelledby="rn-h"><h2 id="rn-h">Renewals due in 60 days</h2>';
  $o .= $rep['renewals'] ? '<ul>' . implode('', array_map(fn($k) => '<li>' . admt_h($k['company_name'] ?? 'Contract #' . $k['id']) . ': ' . admt_h($k['renewal_date']) . ' · ' . admt_h(admf_money((int)$k['amount_minor'], $k['currency'])) . ' ' . admt_h($k['billing_period']) . '</li>', $rep['renewals'])) . '</ul>' : '<p>No active contracts reach a renewal date in the next 60 days.</p>';
  return $o . '</section>';
}

function admf_projects(AdmFinanceStore $s, array $rep, ?string $flash): string {
  $o = '<h1>Projects and retainers</h1><p class="lead">TrustNova enterprise AI projects and recurring retainers from CRM contracts.</p>' . admt_flash($flash) . admf_note($s, $rep); $rows = [];
  foreach (admf_real($s->contracts()) as $k) { $st = admf_stream($k); if (in_array($st, ['project', 'retainer'], true)) { $k['_stream'] = $st; $k['_m'] = crm_contract_measures($k, $rep['as_of']); $rows[] = $k; } }
  if (!$rows) return $o . '<div class="panel"><h2>No project or retainer contracts</h2><p>No TrustNova development contracts are recorded in the CRM yet. No project revenue is estimated.</p></div>';
  $sum = []; foreach ($rows as $k) { $c = $k['currency']; $sum[$c] = $sum[$c] ?? ['mrr' => 0, 'oneoff' => 0, 'n' => 0]; $sum[$c]['mrr'] += $k['_m']['mrr_minor']; $sum[$c]['n']++; if ($k['billing_period'] === 'one_off' && in_array($k['status'], ['active', 'cancelled'], true) && !empty($k['confirmed_at'])) $sum[$c]['oneoff'] += (int)$k['amount_minor']; }
  ksort($sum); $o .= '<section class="panel" aria-labelledby="pj-h"><h2 id="pj-h">Summary</h2><ul>'; foreach ($sum as $c => $x) $o .= '<li><strong>' . admt_h($c) . '</strong>: ' . $x['n'] . ' contract' . ($x['n'] === 1 ? '' : 's') . ' · retainer MRR ' . admt_h(admf_money($x['mrr'], $c)) . ' ' . admf_state('terms') . ' · one-off projects contracted ' . admt_h(admf_money($x['oneoff'], $c)) . ' ' . admf_state('terms') . (isset($rep['concentration'][$c]) ? ' · largest contract is ' . $rep['concentration'][$c] . '% of in-force MRR' : '') . '</li>'; $o .= '</ul></section>';
  $o .= '<section class="panel" aria-labelledby="pl-h"><h2 id="pl-h">Contracts</h2><div class="scroll" role="region" aria-label="Project and retainer contracts" tabindex="0"><table class="fTbl"><thead><tr><th scope="col">Company</th><th scope="col">Type</th><th scope="col">Billing</th><th scope="col" class="num">Amount</th><th scope="col">Status</th><th scope="col">Renewal</th></tr></thead><tbody>';
  foreach ($rows as $k) $o .= '<tr><th scope="row">' . admt_h($k['company_name'] ?? ('#' . $k['id'])) . '</th><td>' . admt_h(ADMF_STREAMS[$k['_stream']]) . '</td><td>' . admt_h(str_replace('_', ' ', $k['billing_period'])) . '</td><td class="num">' . admt_h(admf_money((int)$k['amount_minor'], $k['currency'])) . '</td><td>' . admt_h($k['status']) . (empty($k['confirmed_at']) ? ' (not confirmed)' : '') . '</td><td>' . admt_h($k['renewal_date'] ?? '') . '</td></tr>';
  return $o . '</tbody></table></div></section>';
}

function admf_expenses(AdmFinanceStore $s, array $rep, array $d, array $form, array $errs, ?string $flash, ?string $top): string {
  $o = '<h1>Expenses and profit</h1><p class="lead">Recorded expenses and a cash-basis profit and loss. Corrections are voided with a reason, never deleted.</p>' . admt_flash($flash) . admt_flash($top, true) . admf_note($s, $rep); $ym = admf_ym($rep['as_of']);
  if ($s->finReady()) {
    $o .= '<form class="tForm panel" method="post" action="/admin-center.php?m=finance" novalidate>' . admt_csrf() . '<input type="hidden" name="act" value="fin_expense_add"><h2>Record an expense</h2><div class="row2">' . admt_field('entry_date', 'Date (YYYY-MM-DD)', (string)($form['entry_date'] ?? $rep['as_of']), $errs, 'text', ['required' => true, 'inputmode' => 'numeric', 'maxlength' => '10']);
    $o .= '<label for="f_category">Category<select id="f_category" name="category" required' . (isset($errs['category']) ? ' aria-invalid="true" aria-describedby="f_category_e"' : '') . '><option value="">Choose…</option>'; foreach (ADMF_CATEGORIES as $k => $l) $o .= '<option value="' . $k . '"' . (($form['category'] ?? '') === $k ? ' selected' : '') . '>' . admt_h($l) . '</option>'; $o .= '</select></label>' . (isset($errs['category']) ? '<span class="err" id="f_category_e">' . admt_h($errs['category']) . '</span>' : '') . '</div>';
    $o .= '<div class="row2">' . admt_field('amount', 'Amount', (string)($form['amount'] ?? ''), $errs, 'text', ['required' => true, 'inputmode' => 'decimal']) . '<label for="f_currency">Currency<select id="f_currency" name="currency" required' . (isset($errs['currency']) ? ' aria-invalid="true" aria-describedby="f_currency_e"' : '') . '>'; foreach (crm_currencies() as $c) $o .= '<option' . ((($form['currency'] ?? ADMF_PRIMARY) === $c) ? ' selected' : '') . '>' . $c . '</option>'; $o .= '</select></label>' . (isset($errs['currency']) ? '<span class="err" id="f_currency_e">' . admt_h($errs['currency']) . '</span>' : '') . '</div>';
    $o .= admt_field('description', 'Description', (string)($form['description'] ?? ''), $errs, 'text', ['required' => true, 'maxlength' => '190']) . '<div class="row2">' . admt_field('vendor', 'Vendor (optional)', (string)($form['vendor'] ?? ''), $errs, 'text', ['maxlength' => '80']) . admt_field('reference', 'Document number (optional)', (string)($form['reference'] ?? ''), $errs, 'text', ['maxlength' => '60']) . '</div>';
    $o .= '<div class="row2"><label for="f_recurrence">Repeats<select id="f_recurrence" name="recurrence">'; foreach (['none' => 'One-off', 'monthly' => 'Every month', 'annual' => 'Every year'] as $k => $l) $o .= '<option value="' . $k . '"' . (($form['recurrence'] ?? 'none') === $k ? ' selected' : '') . '>' . $l . '</option>'; $o .= '</select></label>' . admt_field('recurrence_end', 'Stops after (optional, YYYY-MM-DD)', (string)($form['recurrence_end'] ?? ''), $errs, 'text', ['maxlength' => '10']) . '</div>';
    $o .= '<p class="small">Use a document number only. Never enter card, bank or personal data.</p><div class="tActions"><button class="tBtn primary" type="submit">Record expense</button></div></form>';
  } else $o .= '<div class="panel"><h2>Recording is not available</h2><p>The finance storage (migration <code>database/phase8d_finance.sql</code>) is not installed on this server.</p></div>';
  foreach ($rep['currencies'] as $c => $x) { if (!$x['has_expenses'] && !$x['has_revenue']) continue;
    $o .= '<section class="panel" aria-labelledby="pn-' . admt_h($c) . '"><h2 id="pn-' . admt_h($c) . '">Profit and loss, cash basis (' . admt_h($c) . ')</h2><p class="small">' . admf_state('recorded') . ' Net income (received minus refunds) minus expenses, by recorded month. Not an accounting statement.</p><div class="scroll" role="region" aria-label="Profit and loss ' . admt_h($c) . '" tabindex="0"><table class="fTbl"><thead><tr><th scope="col">Month</th><th scope="col" class="num">Net income</th><th scope="col" class="num">Expenses</th><th scope="col" class="num">Profit</th></tr></thead><tbody>';
    foreach (array_reverse($rep['months']) as $m) { $r = $x['series'][$m]; $o .= '<tr><th scope="row">' . admt_h($m) . '</th><td class="num">' . admt_h(admf_money($r['income'], $c)) . '</td><td class="num">' . admt_h(admf_money($r['expenses'], $c)) . '</td><td class="num">' . admt_h(admf_money($r['profit'], $c)) . '</td></tr>'; }
    $o .= '</tbody></table></div></section>'; }
  $cats = admf_by_category($d['expenses'], $ym); foreach ($cats as $c => $items) $o .= admf_chart_hbars('ex-c-' . $c, 'Expenses by category to date (' . $c . ')', 'Cash-basis expenses recorded so far, by category.', $c, $items, 'recorded');
  if (!$cats) $o .= admf_chart_empty('Expenses by category', 'No expenses are recorded yet.');
  $rec = admf_recurring_monthly($d['expenses'], $rep['as_of']);
  if ($rec) { $o .= '<section class="panel" aria-labelledby="rc-h"><h2 id="rc-h">Recurring expenses against recurring revenue</h2><ul>'; foreach ($rec as $c => $v) { $mrr = $rep['currencies'][$c] ?? null; $o .= '<li><strong>' . admt_h($c) . '</strong>: recurring expenses ' . admt_h(admf_money($v, $c)) . ' per month (annual items divided by 12) · ' . ($mrr && $mrr['has_contracts'] ? 'MRR ' . admt_h(admf_money($mrr['mrr'], $c)) . ' ' . admf_state('terms') : 'MRR unavailable (no contracts recorded)') . '</li>'; } $o .= '</ul><p class="small">Runway is <strong>unavailable</strong>: no cash balance is recorded.</p></section>'; }
  $o .= '<section class="panel" aria-labelledby="el-h"><h2 id="el-h">Expense records</h2>'; $exp = array_values(array_filter($d['expenses'], fn($e) => empty($e['is_synthetic'])));
  if (!$exp) return $o . '<p>No expenses are recorded.</p></section>';
  $o .= '<ul class="tRows">'; foreach (array_slice($exp, 0, 100) as $e) { $void = !empty($e['voided_at']);
    $o .= '<li class="tRow"><div><strong>' . admt_h($e['description']) . '</strong> ' . ($void ? '<span class="chip chip-deleted">Voided</span>' : '') . '<br><span class="small">' . admt_h($e['entry_date']) . ' · ' . admt_h(ADMF_CATEGORIES[$e['category']] ?? $e['category']) . ' · ' . admt_h(admf_money((int)$e['amount_minor'], $e['currency'])) . ' · ' . admt_h($e['recurrence'] === 'none' ? 'one-off' : $e['recurrence']) . (($e['vendor'] ?? '') !== '' ? ' · ' . admt_h($e['vendor'] ?? '') : '') . ($void ? ' · reason: ' . admt_h(($e['void_reason'] ?? '')) : '') . '</span></div>';
    if (!$void && $s->finReady()) $o .= '<form method="post" action="/admin-center.php?m=finance" class="tInline">' . admt_csrf() . '<input type="hidden" name="act" value="fin_expense_void"><input type="hidden" name="id" value="' . (int)$e['id'] . '"><label>Reason to void<input type="text" name="reason" minlength="5" maxlength="190" required></label><button class="tBtn danger" type="submit">Void</button></form>'; $o .= '</li>'; }
  return $o . '</ul></section>';
}

function admf_refunds(AdmFinanceStore $s, array $rep, array $d, array $form, array $errs, ?string $flash, ?string $top): string {
  $o = '<h1>Refunds and credit notes</h1><p class="lead">Records against confirmed CRM contracts. A refund returns money; a credit note reduces what is owed. Neither is issued or paid from here.</p>' . admt_flash($flash) . admt_flash($top, true) . admf_note($s, $rep);
  if ($s->finReady()) { $o .= '<form class="tForm panel" method="post" action="/admin-center.php?m=finance" novalidate>' . admt_csrf() . '<input type="hidden" name="act" value="fin_adjustment_add"><h2>Record a refund or credit note</h2><div class="row2"><label for="f_kind">Type<select id="f_kind" name="kind" required><option value="refund"' . (($form['kind'] ?? '') === 'refund' ? ' selected' : '') . '>Refund</option><option value="credit"' . (($form['kind'] ?? '') === 'credit' ? ' selected' : '') . '>Credit note</option></select></label>';
    $o .= '<label for="f_contract_id">Contract<select id="f_contract_id" name="contract_id" required' . (isset($errs['contract_id']) ? ' aria-invalid="true" aria-describedby="f_contract_id_e"' : '') . '><option value="">Choose…</option>'; foreach (admf_real($s->contracts()) as $k) if (in_array($k['status'], ['active', 'cancelled'], true) && !empty($k['confirmed_at'])) $o .= '<option value="' . (int)$k['id'] . '"' . ((int)($form['contract_id'] ?? 0) === (int)$k['id'] ? ' selected' : '') . '>' . admt_h(($k['company_name'] ?? 'Contract') . ' #' . $k['id'] . ' (' . $k['currency'] . ')') . '</option>'; $o .= '</select></label>' . (isset($errs['contract_id']) ? '<span class="err" id="f_contract_id_e">' . admt_h($errs['contract_id']) . '</span>' : '') . '</div>';
    $o .= '<div class="row2">' . admt_field('amount', 'Amount (in the contract currency)', (string)($form['amount'] ?? ''), $errs, 'text', ['required' => true, 'inputmode' => 'decimal']) . admt_field('entry_date', 'Date (YYYY-MM-DD)', (string)($form['entry_date'] ?? $rep['as_of']), $errs, 'text', ['required' => true, 'maxlength' => '10']) . '</div><div class="row2">' . admt_field('reference', 'Document number (optional)', (string)($form['reference'] ?? ''), $errs, 'text', ['maxlength' => '60']) . admt_field('note', 'Note (optional)', (string)($form['note'] ?? ''), $errs, 'text', ['maxlength' => '190']) . '</div><div class="tActions"><button class="tBtn primary" type="submit">Record</button></div></form>'; }
  else $o .= '<div class="panel"><h2>Recording is not available</h2><p>The finance storage is not installed on this server.</p></div>';
  $o .= '<section class="panel" aria-labelledby="ra-h"><h2 id="ra-h">Totals</h2>'; $any = false; foreach ($rep['currencies'] as $c => $x) if ($x['refunds'] || $x['credits']) { $any = true; $o .= '<p><strong>' . admt_h($c) . '</strong>: refunds ' . admt_h(admf_money($x['refunds'], $c)) . ' · credit notes ' . admt_h(admf_money($x['credits'], $c)) . ' ' . admf_state('recorded') . '</p>'; } if (!$any) $o .= '<p>No refunds or credit notes are recorded.</p>'; $o .= '</section>';
  $o .= '<section class="panel" aria-labelledby="rl-h"><h2 id="rl-h">Records</h2>'; $adj = array_values(array_filter($d['adjustments'], fn($a) => empty($a['is_synthetic']))); if (!$adj) return $o . '<p>None yet.</p></section>';
  $o .= '<ul class="tRows">'; foreach (array_slice($adj, 0, 100) as $a) { $void = !empty($a['voided_at']);
    $o .= '<li class="tRow"><div><strong>' . admt_h($a['kind'] === 'credit' ? 'Credit note' : 'Refund') . '</strong> ' . ($void ? '<span class="chip chip-deleted">Voided</span>' : '') . '<br><span class="small">' . admt_h($a['entry_date']) . ' · contract #' . (int)$a['contract_id'] . ' · ' . admt_h(admf_money((int)$a['amount_minor'], $a['currency'])) . (($a['reference'] ?? '') !== '' ? ' · ' . admt_h($a['reference'] ?? '') : '') . ($void ? ' · reason: ' . admt_h(($a['void_reason'] ?? '')) : '') . '</span></div>';
    if (!$void && $s->finReady()) $o .= '<form method="post" action="/admin-center.php?m=finance" class="tInline">' . admt_csrf() . '<input type="hidden" name="act" value="fin_adjustment_void"><input type="hidden" name="id" value="' . (int)$a['id'] . '"><label>Reason to void<input type="text" name="reason" minlength="5" maxlength="190" required></label><button class="tBtn danger" type="submit">Void</button></form>'; $o .= '</li>'; }
  return $o . '</ul></section>';
}

function admf_targets(AdmFinanceStore $s, array $rep, array $get, array $form, array $errs, ?string $flash, ?string $top): string {
  $lad = admf_ladder($rep, $s->targets()); $st = ['reached' => 'Reached', 'not_reached' => 'Not reached', 'no_data' => 'No recorded data', 'not_started' => 'Monitoring not started'];
  $o = '<h1>Targets</h1><p class="lead">Monthly objectives toward ' . admt_h(admf_money(979000 * 100, ADMF_PRIMARY)) . ' per month. ' . admf_state('target') . ' These are aspirations set by the owner, not forecasts and not results.</p>' . admt_flash($flash) . admt_flash($top, true) . admf_note($s, $rep);
  $o .= '<section class="panel" aria-labelledby="ld-h"><h2 id="ld-h">Objective ladder (monitoring starts December 2026)</h2><div class="scroll" role="region" aria-label="Objective ladder" tabindex="0"><table class="fTbl"><thead><tr><th scope="col" class="num">Monthly target</th><th scope="col">Recorded income this month</th><th scope="col">MRR now</th></tr></thead><tbody>';
  foreach ($lad['rows'] as $r) $o .= '<tr><th scope="row" class="num">' . admt_h(admf_money($r['target_minor'], ADMF_PRIMARY)) . '</th><td>' . admt_h($st[$r['income_state']]) . '</td><td>' . admt_h($st[$r['mrr_state']]) . '</td></tr>';
  $o .= '</tbody></table></div><p class="small">' . ($lad['income_minor'] === null ? 'No recorded ' . admt_h(ADMF_PRIMARY) . ' income exists to compare, so no step is marked reached.' : 'Recorded income this month ' . admt_h(admf_money((int)$lad['income_minor'], ADMF_PRIMARY)) . ' ' . admf_state('recorded')) . '</p>';
  if ($lad['income_minor'] !== null && $lad['next_eur'] !== null && $lad['active']) $o .= admf_chart_bullet('tg-b', 'Progress to the next step', max(0, (int)$lad['income_minor']), $lad['next_eur'] * 100, ADMF_PRIMARY, admf_money($lad['next_eur'] * 100, ADMF_PRIMARY) . ' target');
  $o .= '</section>';
  if ($s->finReady()) { $o .= '<form class="tForm panel" method="post" action="/admin-center.php?m=finance" novalidate>' . admt_csrf() . '<input type="hidden" name="act" value="fin_target_set"><h2>Set a month-specific target</h2><p class="small">A new target for a month and measure replaces the previous one, which is kept as superseded. Targets are ' . admt_h(ADMF_PRIMARY) . ' only.</p><div class="row2">' . admt_field('month', 'Month (YYYY-MM, from ' . ADMF_TARGET_START . ')', (string)($form['month'] ?? ADMF_TARGET_START), $errs, 'text', ['required' => true, 'maxlength' => '7']) . '<label for="f_metric">Measure<select id="f_metric" name="metric"><option value="received"' . (($form['metric'] ?? '') !== 'mrr' ? ' selected' : '') . '>Recorded income</option><option value="mrr"' . (($form['metric'] ?? '') === 'mrr' ? ' selected' : '') . '>MRR</option></select></label></div><div class="row2">' . admt_field('amount', 'Target amount (EUR)', (string)($form['amount'] ?? ''), $errs, 'text', ['required' => true, 'inputmode' => 'decimal']) . admt_field('label', 'Label (optional)', (string)($form['label'] ?? ''), $errs, 'text', ['maxlength' => '80']) . '</div><div class="tActions"><button class="tBtn primary" type="submit">Save target</button></div></form>'; }
  $o .= '<section class="panel" aria-labelledby="ct-h"><h2 id="ct-h">Owner targets</h2>'; $cust = array_values(array_filter($s->targets(), fn($t) => true)); if (!$cust) $o .= '<p>No month-specific targets are set. The objective ladder above applies.</p>'; else { $o .= '<ul class="tRows">'; foreach ($cust as $t) $o .= '<li class="tRow"><div><strong>' . admt_h(substr((string)$t['month'], 0, 7)) . ' · ' . admt_h($t['metric'] === 'mrr' ? 'MRR' : 'Recorded income') . '</strong>: ' . admt_h(admf_money((int)$t['amount_minor'], $t['currency'])) . ' ' . (empty($t['superseded_at']) ? admf_state('target') : '<span class="chip chip-unpublished">Superseded</span>') . ($t['label'] !== '' ? '<br><span class="small">' . admt_h($t['label']) . '</span>' : '') . '</div></li>'; $o .= '</ul>'; }
  $o .= '</section>' . admf_scenario_view($rep, $get);
  return $o;
}
function admf_scenario_view(array $rep, array $get): string {
  $in = array_intersect_key($get, array_flip(['v_customer', 'v_contract', 'v_subscription', 'v_partnership', 'm_customer', 'm_contract', 'm_subscription', 'm_partnership', 'close_rate'])); $sc = admf_scenario($in); $submitted = isset($get['calc']);
  $o = '<section class="panel fScen" aria-labelledby="sc-h"><h2 id="sc-h">Scenario calculator ' . admf_state('hypothetical') . '</h2><p class="small">Type what one customer, contract, subscription or partnership is worth per month. Nothing is stored and nothing is assumed: the table is arithmetic on your inputs, not a forecast. Mix and close rate are optional.</p>';
  $e = $rep['currencies'][ADMF_PRIMARY] ?? null; if ($e && $e['has_contracts']) { $n = 0; foreach ($rep['currencies'][ADMF_PRIMARY]['streams'] as $s) $n += $s['contracts']; $o .= '<p class="small">Recorded for reference ' . admf_state('terms') . ': current MRR ' . admt_h(admf_money($e['mrr'], ADMF_PRIMARY)) . ' across ' . (int)$n . ' contract' . ($n === 1 ? '' : 's') . '.</p>'; }
  $o .= '<form class="tForm" method="get" action="/admin-center.php"><input type="hidden" name="m" value="finance"><input type="hidden" name="view" value="targets"><input type="hidden" name="calc" value="1"><div class="row2">';
  foreach ($sc['types'] as $k => $l) $o .= admt_field('v_' . $k, 'Monthly value of one: ' . $l . ' (EUR)', (string)($get['v_' . $k] ?? ''), $sc['errors'], 'text', ['inputmode' => 'decimal']);
  $o .= '</div><div class="row2">'; foreach ($sc['types'] as $k => $l) $o .= admt_field('m_' . $k, 'Mix: ' . $l . ' (percent)', (string)($get['m_' . $k] ?? ''), $sc['errors'], 'text', ['inputmode' => 'numeric', 'maxlength' => '3']);
  $o .= '</div>' . (isset($sc['errors']['mix']) ? '<span class="err" role="alert">' . admt_h($sc['errors']['mix']) . '</span>' : '') . admt_field('close_rate', 'Close rate (percent of leads that become one, optional)', (string)($get['close_rate'] ?? ''), $sc['errors'], 'text', ['inputmode' => 'numeric', 'maxlength' => '3']) . '<div class="tActions"><button class="tBtn primary" type="submit">Calculate</button></div></form>';
  if ($sc['errors']) $o .= '<p class="err" role="alert">Please correct the highlighted inputs.</p>';
  elseif ($submitted && !$sc['unit']) $o .= '<p class="warn">Enter at least one monthly value to calculate.</p>';
  elseif ($sc['rows']) { $o .= '<div class="scroll" role="region" aria-label="Scenario results" tabindex="0"><table class="fTbl"><caption>' . admf_state('hypothetical') . ' How many it takes to reach each monthly target, using only your inputs</caption><thead><tr><th scope="col" class="num">Monthly target</th>';
    foreach ($sc['unit'] as $k => $u) $o .= '<th scope="col" class="num">' . admt_h($sc['types'][$k]) . ' needed</th>'; if ($sc['mix']) foreach ($sc['mix'] as $k => $p) if ($p > 0 && isset($sc['unit'][$k])) $o .= '<th scope="col" class="num">In the mix: ' . admt_h($sc['types'][$k]) . ' (' . (int)$p . '%)</th>'; $o .= '</tr></thead><tbody>';
    foreach ($sc['rows'] as $r) { $o .= '<tr><th scope="row" class="num">' . admt_h(admf_money($r['eur'] * 100, ADMF_PRIMARY)) . '</th>'; foreach ($sc['unit'] as $k => $u) $o .= '<td class="num">' . number_format($r['single'][$k]['count']) . ($r['single'][$k]['leads'] !== null ? '<br><span class="small">' . number_format($r['single'][$k]['leads']) . ' leads</span>' : '') . '</td>'; foreach ($sc['mix'] as $k => $p) if ($p > 0 && isset($sc['unit'][$k])) $o .= '<td class="num">' . number_format($r['mixed'][$k]['count']) . ($r['mixed'][$k]['leads'] !== null ? '<br><span class="small">' . number_format($r['mixed'][$k]['leads']) . ' leads</span>' : '') . '</td>'; $o .= '</tr>'; }
    $o .= '</tbody></table></div><p class="small">Each "needed" column assumes the whole target comes from that one type. The mix columns split each target by your percentages. Counts are rounded up.</p>'; }
  return $o . '</section>';
}

function admf_exports(AdmFinanceStore $s, array $rep, ?string $flash): string {
  $o = '<h1>Exports</h1><p class="lead">CSV files for the owner. Every row says what kind of figure it is; amounts are plain numbers per currency and are never mixed. Each export is recorded in the audit log.</p>' . admt_flash($flash) . admf_note($s, $rep) . '<ul class="tRows">';
  foreach (ADMF_EXPORTS as $k => $l) $o .= '<li class="tRow"><div><strong>' . admt_h($l) . '</strong></div><a class="tBtn" href="' . admt_h(admf_url(['export' => $k])) . '">Download CSV</a></li>'; return $o . '</ul>';
}

/** Router. $form/$errs/$top carry a failed POST back to its screen. */
function admf_body(AdmFinanceStore $s, array $user, array $get, ?array $form = null, array $errs = [], ?string $top = null): string {
  if (!adm_can((string)($user['role'] ?? ''), 'finance')) return '<h1>Not allowed</h1>';
  $view = (string)($get['view'] ?? 'overview'); $flash = isset($get['msg']) && is_string($get['msg']) ? (admf_messages()[$get['msg']] ?? null) : null; $d = admf_load($s); $rep = admf_report($d); $nav = admf_nav($s, $view); $form = $form ?? [];
  switch ($view) {
    case 'revenue': return $nav . admf_revenue($s, $rep, $flash);
    case 'advertising': return $nav . admf_advertising($s, $rep, $flash);
    case 'projects': return $nav . admf_projects($s, $rep, $flash);
    case 'expenses': return $nav . admf_expenses($s, $rep, $d, $form, $errs, $flash, $top);
    case 'refunds': return $nav . admf_refunds($s, $rep, $d, $form, $errs, $flash, $top);
    case 'targets': return $nav . admf_targets($s, $rep, $get, $form, $errs, $flash, $top);
    case 'exports': return $nav . admf_exports($s, $rep, $flash);
  }
  return admf_nav($s, 'overview') . admf_overview($s, $rep, $d, $flash);
}
/** POST entry (after the CSRF and same-origin check in admin-center.php). Redirects (303) on success, re-renders the screen on error. */
function admf_handle_post(AdmFinanceStore $s, array $user, array $post, callable $audit): array {
  $act = is_string($post['act'] ?? null) ? substr($post['act'], 4) : ''; $r = admf_apply($s, $user, $act, $post, $audit);
  if ($r['ok']) return ['redirect' => admf_url($r['goto'] + ['msg' => $r['msg']]), 'code' => 303];
  return ['code' => $r['code'], 'form' => $post, 'errs' => $r['errors'], 'top' => $r['errors']['_'] ?? $r['msg'], 'get' => ['m' => 'finance'] + ($r['get'] ?: ['view' => 'overview'])];
}
function admf_not_installed(): string { return '<h1>Finance</h1><div class="panel"><h2>Finance reports could not be read</h2><p>The CRM tables are not available on this server, so there is nothing to report. Nothing is estimated.</p></div>'; }
